/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Process Price Change tracking records for Products and create Price Data Feed records
/// </summary>
using System.ComponentModel.Composition;
[Export(identifierStr(Dynamics.AX.Application.METPriceChangeTrack))]
[ExportMetadata(enumStr(METPriceChangeType), enumLiteralStr(METPriceChangeType, Customer))]
public class METPriceChangeTrackCustomer extends METPriceChangeTrack
{
}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <param name = "_showValidation">Show validation</param>
public void initInstance(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    this.setInternals(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <param name = "_showValidation">Show validation</param>
public void setInternals(METPriceChangeTracking _priceChangeTracking, boolean _showValidation)
{
    super(_priceChangeTracking, _showValidation);
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>Price change type</returns>
public METPriceChangeType getPriceChangeType()
{
    return METPriceChangeType::Customer;
}

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void process()
    {
        priceDataFeedCount = 0;
        priceDataFeedList = this.createPriceDataFeedList();

        this.processStd();

        if(priceDataFeedCount)
        {
            ttsbegin;
            priceDataFeedList.insertDatabase();
            ttscommit;
        }
    }

    /// <summary>
    /// Process the Change tracking record
    /// </summary>
    public void processStd()
    {
        InventTable inventTable;
        boolean     validityCheck, validityCheck1, validityCheck2, validityCheck3;
        str         message;

        while select ItemId
            from    inventTable
        {
            validityCheck = false;
            validityCheck1 = false;
            validityCheck2 = false;
            validityCheck3 = false;
            message = METConstants::emptyString;

            //1. Execute the Item/Site validity check
            validityCheck = this.ItemSiteValidation(inventTable.ItemId, priceChangeTrackingOrig.InventSiteId);

            if(validityCheck)
            {
                //If Customer/item validity check 1 returns True OR (check 2 and check 3 both returned True) then an entry is required in the Price feed table
                
                //Customer/item validity check 1
                [validityCheck1, message] = this.customerItemValidationProfile(priceChangeTrackingOrig.CustAccount, inventTable.ItemId);

                if(!validityCheck1)
                {
                    //Customer/item validity check 2
                    [validityCheck2, message] = this.customerItemValidationSellTo(priceChangeTrackingOrig.CustAccount, inventTable.ItemId);

                    if(validityCheck2)
                    {
                        //Customer/item validity check 3
                        [validityCheck3, message] = this.customerItemValidationDoNotSellTo(priceChangeTrackingOrig.CustAccount, inventTable.ItemId);
                    }
                }

                if(validityCheck1 || (validityCheck2 && validityCheck3))
                {
                    //process record
                    this.processCustomer(inventTable.ItemId);
                }
            }
        }
    }

    public void processCustomer(ItemId _itemId)
    {
        METPriceChangeTracking priceChangeTrackingUpdate;

        //update values for processing, but dont committ to DB
        buf2Buf(priceChangeTrackingOrig, priceChangeTrackingUpdate);

        priceChangeTrackingUpdate.PriceDiscAccountRelation  = priceChangeTrackingOrig.CustAccount;
        priceChangeTrackingUpdate.ItemId                    = _itemId;
        priceChangeTrackingUpdate.UnitId                    = InventTableModule::find(_itemId, ModuleInventPurchSales::Sales).UnitId;

        this.createPriceDataFeedAll(priceChangeTrackingUpdate, 1, METConstants::emptyString);
        
    }

/// <summary>
/// Get the Id of the record that caused the change
/// </summary>
/// <param name = "_priceChangeTracking">Price change track record</param>
/// <returns>Id of the record</returns>
public METChangeCode getChangeCode(METPriceChangeTracking _priceChangeTracking)
{
    return _priceChangeTracking.CustAccount;
}

/// <summary>
/// Get the type of the record that caused the change
/// </summary>
/// <returns>Type of the record</returns>
public METCreationType getOriginalCreationType()
{
    return METCreationType::Original;
}

/// <summary>
/// Get the type of the related record
/// </summary>
/// <returns>Related type</returns>
public METCreationType getRelatedCreationType()
{
    return METCreationType::Related;
}

    /// <summary>
    /// Created the Related records
    /// </summary>
    /// <param name = "_priceChangeTracking">Price change track record</param>
    /// <param name = "_lineNumberOrig">Line number of original record</param>
    public void createRelatedComponents(METPriceChangeTracking _priceChangeTracking, LineNumber _lineNumberOrig)
    {
        //Margin Component
        this.createRelatedPriceAdj(_priceChangeTracking, _lineNumberOrig, [RetailDiscountOfferTypeBase::Promotion], METCreationType::RelatedMarginComponent);
        
        //Discount
        this.createRelatedPriceAdj(_priceChangeTracking, _lineNumberOrig, [RetailDiscountOfferTypeBase::Multibuy, RetailDiscountOfferTypeBase::DiscountOffer], METCreationType::RelatedDiscount);

        //Autocharge
        this.createRelatedAutoCharge(_priceChangeTracking, _lineNumberOrig);
    }
